class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def min_moves(target: int) -> int:
            need = [(target + p - 1) // p for p in points]

            def prefix_sum(i: int) -> int:
                return (i + 1) * i // 2

            def suffix_sum(i: int) -> int:
                return (2 * n - i - 1) * (n - i) // 2

            best = 0

            # End at the rightmost position.
            ans = prefix_sum(n - 1) + sum(need)
            best = ans

            # End at position end.
            for end in range(n - 1):
                ans = prefix_sum(end) + suffix_sum(end + 1) + sum(need)
                if ans < best:
                    best = ans

                # If the final visit to 'end' is not counted by the base walk,
                # add one extra visit to the final position.
                if end >= 1 and need[end] > need[end - 1] + need[end + 1]:
                    ans += 1
                    if ans < best:
                        best = ans

            return best

        lo, hi = 0, max(points) * m + 1
        while lo + 1 < hi:
            mid = (lo + hi) // 2
            if min_moves(mid) <= m:
                lo = mid
            else:
                hi = mid - 1

        return lo
