class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        if k <= 1:
            return 0

        n = len(points)

        # Map every boundary point to a circular coordinate along the square boundary.
        # For points on the boundary of an axis-aligned square, the Manhattan distance
        # is the minimum of the clockwise and counter-clockwise boundary distances.
        def boundary_coord(x: int, y: int) -> int:
            if y == 0:                 # bottom side: (0, 0) -> (side, 0)
                return x
            if x == side:              # right side: (side, 0) -> (side, side)
                return side + y
            if y == side:              # top side: (side, side) -> (0, side)
                return 2 * side + (side - x)
            # left side: (0, side) -> (0, 0)
            return 3 * side + (side - y)

        coords = sorted(boundary_coord(x, y) for x, y in points)
        perimeter = 4 * side

        # Check whether it is possible to choose k points whose pairwise
        # Manhattan distances are all at least dist.
        def can(dist: int) -> bool:
            if dist == 0:
                return True

            # For each starting point i, greedily choose as many points as possible
            # clockwise with boundary distance >= dist. Since the chosen points are
            # in clockwise order, ensuring consecutive chosen points are at least
            # dist apart also ensures all pairwise distances are at least dist
            # (because the wrap-around distance is at least as large).
            for i in range(n):
                chosen = 1
                current = coords[i]

                for j in range(1, n):
                    nxt = coords[(i + j) % n]
                    clockwise = nxt - current
                    if clockwise < 0:
                        clockwise += perimeter

                    if clockwise >= dist:
                        chosen += 1
                        if chosen >= k:
                            return True
                        current = nxt

            return False

        # Binary search the maximum feasible minimum Manhattan distance.
        lo, hi = 0, 2 * side
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo
