        events = []
        total_area = 0

        for _, y, length in squares:
            total_area += length * length
            events.append((y, length))
            events.append((y + length, -length))

        events.sort()

        target = total_area / 2.0
        current_width = 0
        below = 0.0
        prev_y = events[0][0]
        i = 0
        n = len(events)

        while i < n:
            y = events[i][0]

            if y > prev_y and current_width > 0:
                below += current_width * (y - prev_y)

            if below >= target:
                return float(prev_y)

            while i < n and events[i][0] == y:
                current_width += events[i][1]
                i += 1

            if below < target and current_width > 0:
                needed = target - below
                return float(prev_y + needed / current_width)

            prev_y = y

        return float(prev_y)
